parameters.jsCode:
// Claude replies with a JSON object as text — parse it defensively.
// Anything unparseable goes to the exceptions branch instead of being lost.
const out = [];
for (const item of $input.all()) {
  const raw = item.json?.content?.[0]?.text ?? '';
  try {
    const m = raw.match(/\{[\s\S]*\}/);
    if (!m) throw new Error('no JSON in model reply');
    const data = JSON.parse(m[0]);
    out.push({ json: { ok: true, ...data, raw_subject: $('Email Trigger (IMAP)').item.json.subject } });
  } catch (e) {
    out.push({ json: { ok: false, error: String(e), raw_reply: raw.slice(0, 500), raw_subject: $('Email Trigger (IMAP)').item.json.subject } });
  }
}
return out;
